function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
for(const [stage,label]of Object.entries(stageLabels)){const group=el('details',undefined,'stage');group.open=stage==='B';group.append(el('summary',label));const nav=el('nav');nav.setAttribute('aria-label',label+'学科');for(const[sub,text]of Object.entries(subjectLabels)){if(['C','D'].includes(stage)&&sub==='P')continue;const a=el('a',text);a.href=`#map/${stage}/${sub}`;nav.append(a)}group.append(nav);document.querySelector('#map-menu').append(group)}
