function draw(item,kind){if(kind==='week'){const article=el('article',undefined,'card');const a=el('a','第'+item.day+'天 · '+item.title);a.href='#lesson/'+location.hash.split('/')[1]+'/'+item.day+'/all';article.append(el('h3'),a,el('p',item.point_ids.join(' · ')),el('p',item.sample?'三页PDF已生成，可预览下载':'教案已规划，PDF尚未生成'));cards.append(article);return;}if(kind==='lesson'){const article=el('article',undefined,'card lesson-card');article.append(el('span',item.id+' · '+subjectLabels[item.subject],'code'),el('h3',item.title),el('p',item.mode+' · '+item.duration));for(const id of item.point_ids){const a=el('a',id);a.href='#map/'+id[0]+'/'+id[2];article.append(a,document.createTextNode(' '))}article.append(el('h4','打印页原稿'),el('p',item.print_text,'print-copy'),el('h4','活动'),el('p',item.activity),el('h4','家长引导'),el('p',item.parent_guide),el('h4','观察与反馈'),el('p',item.observation),el('p','反馈预留：偏易 / 合适 / 偏难；独立 / 提示后 / 暂未尝试。直接在聊天告诉我；这里尚未记录任何结果。','prereq'));cards.append(article);return;}const article=el('article',undefined,'card');article.append(el('span',item.id,'code'),el('h3',item.title||item.value,kind==='inventory'?'word':''));if(kind==='inventory'){article.append(el('p',item.group),el('p',item.scope));}else if(item.objective){article.append(el('p',item.objective));const detail=el('details');detail.append(el('summary','怎么观察 / 练习'),el('p',item.activity),el('p',item.prerequisites.length?'前置：'+item.prerequisites.join('、'):'无指定硬前置，可从当前能力尝试','prereq'));if(item.placement)detail.append(el('p',item.placement,'prereq'));for(const source of item.evidence||[]){const a=el('a','依据：'+source.section);a.href=source.url;a.target='_blank';a.rel='noopener';detail.append(a)}article.append(detail)}else article.append(el('p',item.note));cards.append(article)}
function progressive(items,kind,token){let offset=0;appendNext=()=>{if(token!==sequence)return;const end=Math.min(offset+12,items.length);for(;offset<end;offset++)draw(items[offset],kind);more.hidden=offset===items.length;status.textContent=items.length?'':'这个分类暂时没有内容。请选择其他学科。';if(more.hidden)observer?.disconnect()};appendNext();if(!more.hidden&&'IntersectionObserver'in window){observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))appendNext?.()},{rootMargin:'200px'});observer.observe(more)}}
